export const CARD_WIDTH = 1488;
export const CARD_HEIGHT = 2079;

export function cardById(id: number): Card | undefined {
  return CARDS.find((c) => c.id === id);
}

export function cardImage(id: number): string {
  return `/cards/card${id}.webp`;
}

/** Card back, shared by all cards. */
export const CARD_BACK = "/cards/back.png";

/**
 * Form colours for places that can't use CSS: the browser theme-color on the
 * card page and the OG image. Copied from `html:has([data-form-theme])` in
 * globals.css, so keep the two in sync.
 */
export const FORM_THEME: Record<Form, { background: string; line: string; text: string; accent: string }> = {
  Luce: { background: "#f4e5c0", line: "#c6a668", text: "#241a0f", accent: "#7d5a0d" },
  Ombra: { background: "#e5dff5", line: "#a294cf", text: "#181033", accent: "#4c3b91" },
  Duale: { background: "#f6e1d0", line: "#d5a682", text: "#2c1409", accent: "#9a4420" },
};
